// Rows is the product of every axis but the first: how many NE[0]-long rows
// Values holds.
func (d *Dump) Rows() int {
	n := int64(1)
	for _, v := range d.NE[1:] {
		if v > 0 {
			n *= v
		}
	}
	return int(n)
}

// Row returns row i, of NE[0] values.
func (d *Dump) Row(i int) []float32 {
	w := int(d.NE[0])
	return d.Vals[i*w : (i+1)*w]
}

