2	// tensors rather than the 3-per-axis corners `llama-eval-callback` prints, so
3	// that the Go implementation of a layer can be checked value for value
4	// instead of against a sum.
5	//
6	// It is the oracle for LLM.md's L2 onwards, the same way reference/
7	// dequant_ref.c is the oracle for gguf/dequant.go: it links against the
8	// already-built libllama and registers the *same* eval callback the scheduler
9	// hands every node, so what it records is the reference implementation's own
10	// tensors and not a re-reading of its source.
11	//
12	//	L=/home/kube/repos/llama.cpp
13	//	gcc -O2 -o /tmp/eval_dump reference/eval_dump.c \
14	//	    -I$L/include -I$L/ggml/include -L$L/build/bin \
15	//	    -lllama -lggml-base -Wl,-rpath,$L/build/bin
16	//	/tmp/eval_dump -m MODEL.gguf -o DIR -p 'hello world' -n 'regex'
17	//	/tmp/eval_dump -m MODEL.gguf -o DIR -f prompt.txt -nt 4096 -c 4096 -n 'regex'
18	//
19	// `-f` reads the prompt from a file and `-nt` truncates the token list to an
20	// exact length, which is how L4's 4 k fixture is cut: the QSA selection only
21	// starts excluding cells past `top_k + ratio - 1` = 2051, so the dump that
22	// tests it has to be longer than that and a round 4096 makes the block
23	// arithmetic legible.
24	//
