			worst = d
		}
	}
	t.Logf("indexer_score_tokens-3 %.0f finite cells of %d, worst |diff| %.3e", finite, len(want.Vals), worst)
	if worst > 1.0 {
		t.Errorf("indexer_score_tokens-3: worst finite disagreement %.3e", worst)
	}
