9	// L4: the QSA selection, at the only context length where it exists.
10	//
11	// Everything in L2 and L3 was checked against a 7-token dump, and at 7 tokens
12	// this block is a no-op: the reference asks for `top_k + ratio - 1` = 2051
13	// cells out of a 256-cell cache, so it names every one of them and running
14	// the attention with the selection is bit-identical to running it without
15	// (TestAttnTopKCannotBiteHere). A second dump at 4096 tokens in a 4096-cell
16	// cache is where the width finally binds — 2051 of 4096 — and where the two
17	// questions L2e left open can be asked at all: what the selection *is*, and
18	// whether ours is the reference's.
19	//
20	// The fixture is a second trace directory rather than a replacement, because
21	// the 7-token one is still the only place a great many things are legible:
22	// the empty blocks that pool cell zero, the spare block, the f32 vector path
23	// that L3a-5 found the reference takes below 8 output columns. The two are
24	// complementary and both are kept.
25	const (
26		traceDir4k  = "../reference/out/llm4k"
27		regenHint4k = `run:
28	  L=/home/kube/repos/llama.cpp
29	  H=$(mktemp -d) && (cd $L && git archive cff184438 include ggml/include | tar -x -C $H)
30	  gcc -O2 -o /tmp/eval_dump reference/eval_dump.c -I$H/include -I$H/ggml/include \
31	      -L$L/build/bin -lllama -lggml-base -Wl,-rpath,$L/build/bin
32	  mkdir -p reference/out/llm4k
33	  head -c 40000 models/wikitext-2-raw/wiki.test.raw | head -n -1 > reference/out/llm4k/prompt.txt
34	  /tmp/eval_dump -m $M -o reference/out/llm4k -f reference/out/llm4k/prompt.txt \
35	      -nt 4096 -c 4096 -ub 4096 \
36	      -n '^(model\.input_embed|ple_embd|hc_init)$|-(0|3)$|^ple_(gate|gated_value|conv_out)-1$'
37	  (8.0 GB, ~4 minutes; the headers are pinned to the *build* in $L/build/bin,
38	   which is cff184438 even when the checkout has moved past it)`
39	)
40	
41	// fixtures4k is the 4096-token trace beside the 7-token one.
42	func fixtures4k(t *testing.T) (*Model, *Trace) {
43		t.Helper()
44		if _, err := os.Stat(modelDir); err != nil {
45			t.Skipf("checkpoint absent: %v", err)
46		}
47		if _, err := os.Stat(traceDir4k); err != nil {
48			t.Skipf("4k reference trace absent (%v); %s", err, regenHint4k)
49		}
50		tr, err := OpenTrace(traceDir4k)
51		if err != nil {
52			t.Skipf("4k reference trace unusable (%v); %s", err, regenHint4k)
53		}
54		m, err := Open(modelDir)
55		if err != nil {
56			t.Fatalf("open checkpoint: %v", err)
57		}
58		t.Cleanup(func() { m.Close() })
59		return m, tr
60	}
61	
62	// qsaFixtures4k opens layer 3 at 4096 tokens and returns the reference's own
63	// selection beside it. nKV is read off the dump, not assumed: it is the
64	// padded cell count and every part of the indexer is cut against it.
65	func qsaFixtures4k(t *testing.T) (c AttnConfig, w AttnWeights, nTok, nKV, width int, tr *Trace, topk *Dump) {
66		t.Helper()
67		m, tr := fixtures4k(t)
68		c, ok, err := m.AttnConfig(attnLayer)
69		if err != nil || !ok {
70			t.Fatalf("layer %d attention config: %v (present %v)", attnLayer, err, ok)
71		}
72		if w, err = m.AttnWeights(attnLayer); err != nil {
73			t.Fatal(err)
74		}
75		ids, _, err := tr.Tokens()
76		if err != nil {
77			t.Fatal(err)
78		}
79		nTok = len(ids)
