86			t.Fatal(err)
87		}
88		if topk.Ints == nil {
89			t.Fatalf("indexer_top_k-3 is ggml type %d, want an integer tensor", topk.GType)
90		}
91		width = int(topk.NE[0])
92		return c, w, nTok, nKV, width, tr, topk
93	}
