95	// TestQSASelectionBitesAt4k is the precondition every other test in this file
96	// rests on, asserted rather than assumed: at 4096 cells the width is 2051, so
97	// the selection removes cells the causal mask allows.
98	//
99	// It also locates exactly where that starts. A token at position i has i+1
100	// visible cells, so the first token whose selection can drop anything is
101	// i = width, and the reference's own output says so.
102	func TestQSASelectionBitesAt4k(t *testing.T) {
103		_, _, nTok, nKV, width, _, topk := qsaFixtures4k(t)
104		if width >= nKV {
105			t.Fatalf("width %d of %d cells: the selection still cannot bite, so this dump is too short", width, nKV)
106		}
107		t.Logf("%d tokens, %d cells, top-k width %d — %d cells a token are unreachable",
108			nTok, nKV, width, nKV-width)
109	
110		first := -1
111		var worstDropped int
112		for i := 0; i < nTok; i++ {
113			sel := map[int32]bool{}
114			for _, cell := range topk.Ints[i*width : (i+1)*width] {
115				sel[cell] = true
116			}
117			dropped := 0
118			for j := 0; j <= i; j++ {
119				if !sel[int32(j)] {
120					dropped++
121				}
122			}
123			if dropped > 0 && first < 0 {
124				first = i
125			}
126			if dropped > worstDropped {
127				worstDropped = dropped
128			}
129			if dropped > 0 && i+1 <= width {
130				t.Errorf("token %d has %d visible cells and drops %d, but the width is %d", i, i+1, dropped, width)
131			}
132		}
133		if first < 0 {
134			t.Fatal("no token drops a visible cell: the selection is still a no-op")
