141			t.Errorf("the last token drops %d visible cells, want %d", worstDropped, want)
142		}
143	}
144	
145	// TestQSASelectionIsARadixSelect is the L4 gate on the selection itself, and
146	// it is deliberately fed llama.cpp's *own* per-cell scores rather than ours:
147	// what is under test is the selection rule, not the arithmetic in front of it.
148	//
149	// The rule is `topk_radix_select.comp`, and it is not a sort. It finds the key
150	// of the width-th largest value by four 8-bit radix passes, emits every cell
151	// **strictly above** it, and then fills the remainder from the cells **equal**
